From c8474b471be3c6e9040d811539262698f78a3442 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 10:48:54 +0100
Subject: [PATCH] krunner: place the top bar below floating panels

Floating panels only reserve their thickness, so KRunner at the top of
the screen overlapped the gap under a floating top panel. It now asks
plasmashell for the space panels really take and places itself below it.

BUG: 502508
---
 krunner/view.cpp | 37 ++++++++++++++++++++++++++-----------
 krunner/view.h   |  1 +
 2 files changed, 27 insertions(+), 11 deletions(-)

diff --git a/krunner/view.cpp b/krunner/view.cpp
index 1ca6e0d0f1..afdb5ff743 100644
--- a/krunner/view.cpp
+++ b/krunner/view.cpp
@@ -103,7 +103,7 @@ QMargins View::margins()
         const QRect r = screen()->availableGeometry();
         return QMargins({0, r.height() / 3, 0, 0});
     } else {
-        return {}; // Zeros
+        return QMargins({0, m_panelMargin, 0, 0});
     }
 }

@@ -158,17 +158,31 @@ void View::showEvent(QShowEvent *event)
 void View::positionOnScreen()
 {
     const auto screens = QGuiApplication::screens();
+    QScreen *activeScreen = screen();
+    auto message = QDBusMessage::createMethodCall(u"org.kde.KWin"_s, u"/KWin"_s, u"org.kde.KWin"_s, u"activeOutputName"_s);
+    QDBusReply<QString> reply = QDBusConnection::sessionBus().call(message);
+    if (reply.isValid()) {
+        const QString activeOutputName = reply.value();
+        const auto screenIt = std::ranges::find_if(screens, [&activeOutputName](QScreen *screen) {
+            return screen->name() == activeOutputName;
+        });
+        if (screenIt != screens.end()) {
+            activeScreen = *screenIt;
+        }
+    }
     if (m_floating) {
-        auto message = QDBusMessage::createMethodCall(u"org.kde.KWin"_s, u"/KWin"_s, u"org.kde.KWin"_s, u"activeOutputName"_s);
-        QDBusReply<QString> reply = QDBusConnection::sessionBus().call(message);
-        if (reply.isValid()) {
-            const QString activeOutputName = reply.value();
-            const auto screenIt = std::ranges::find_if(screens, [&activeOutputName](QScreen *screen) {
-                return screen->name() == activeOutputName;
-            });
-            if (screenIt != screens.end()) {
-                setScreen(*screenIt);
-            }
+        setScreen(activeScreen);
+    }
+
+    // Panels only reserve their thickness; plasmashell also counts the floating gap
+    m_panelMargin = 0;
+    if (!m_floating) {
+        auto strutMessage =
+            QDBusMessage::createMethodCall(u"org.kde.plasmashell"_s, u"/StrutManager"_s, u"org.kde.PlasmaShell.StrutManager"_s, u"availableScreenRect"_s);
+        strutMessage << activeScreen->name();
+        QDBusReply<QRect> strutReply = QDBusConnection::sessionBus().call(strutMessage);
+        if (strutReply.isValid()) {
+            m_panelMargin = std::max(0, strutReply.value().top() - activeScreen->geometry().top());
         }
     }

@@ -178,6 +192,7 @@ void View::positionOnScreen()
     layerWindow->setScope(u"krunner"_s);
     layerWindow->setKeyboardInteractivity(LayerShellQt::Window::KeyboardInteractivityOnDemand);
     layerWindow->setMargins(margins());
+    layerWindow->setExclusiveZone(m_panelMargin > 0 ? -1 : 0);
     if (m_floating) {
         layerWindow->setScreen(screen());
     } else {
diff --git a/krunner/view.h b/krunner/view.h
index 5c0d01accc..3464ce4995 100644
--- a/krunner/view.h
+++ b/krunner/view.h
@@ -109,6 +109,7 @@ private:
     KConfigGroup m_stateData;
     KConfigWatcher::Ptr m_configWatcher;
     bool m_floating = false;
+    int m_panelMargin = 0;
     bool m_pinned = false;
     bool m_retainPriorSearch = false;
     bool m_requestedClipboardSelection = false;
